// #a4899f (№32) «Android - בפרק תהילים כפתור הפרק הנוכחי מסתיר את «פרק הקודם/הבא» בזום 200%» — עבר QA 09.11.
//   מה רצוי: «בזום 200% הכפתורים «פרק קודם», הפרק הנוכחי ו«פרק הבא» לא עולים זה על זה, והטקסטים נקראים במלואם».
//   Было (תהילים ג׳): «פרק ב׳» закрыт кругом «ג׳», «פרק ד׳» виден как «רק ד׳».
// Факт 09.11 (Pixel 6, wm density 840): «פרק ב׳» / «ג׳» / «פרק ד׳» без наложения (751dfff).
// Кейс: .qa/tests/zoom-200/Z2-08-chapter-nav.md. Только просмотр.
import { driver, expect } from '@wdio/globals';
import { goHome } from '../_lib/readiness-1910.ts';
import { openTehilimChapter, skipWith } from '../_lib/app-0710.ts';
import { scrollToText } from '../../helpers/ui.ts';
import { zoomOn, zoomOff, textNode, insideScreenX, overlaps, notTruncated, saveShot } from '../_lib/app-0911.ts';

const PREV = 'פרק ב׳';
const NEXT = 'פרק ד׳';
const CUR = 'ג׳';

async function navNodes() {
  await scrollToText(NEXT);
  const { height } = await driver.getWindowSize();
  const prev = await textNode(PREV);
  const next = await textNode(NEXT);
  // Текущая глава — «ג׳» на одной высоте с соседями (не заголовок «תהילים ג׳» и не строка списка).
  const cur = await textNode(CUR, (n) => Math.abs(n.y + n.h / 2 - (prev.y + prev.h / 2)) < height * 0.06);
  return { prev, cur, next };
}

describe('09.11 — зум 200% (Android): навигация между главами תהילים (#a4899f)', () => {
  before(function () { if (!driver.isAndroid) skipWith(this, 'зум через wm density — только Android'); });
  after(async () => { if (driver.isAndroid) await zoomOff(); });

  it('Z2-08 При wm density 840 в תהילים ג׳ «פרק ב׳», кружок «ג׳» и «פרק ד׳» не налезают друг на друга и видны целиком #a4899f @android @prod-safe @manual-check', async () => {
    await openTehilimChapter(3);
    const n = await navNodes();

    await goHome();
    await zoomOn();
    await openTehilimChapter(3);
    const z = await navNodes();
    await saveShot('q33-chapter-nav.png');
    console.log(`[Q-33] «${PREV}» x${z.prev.x}..${z.prev.x + z.prev.w}; «${CUR}» x${z.cur.x}..${z.cur.x + z.cur.w}; «${NEXT}» x${z.next.x}..${z.next.x + z.next.w}`);

    expect(overlaps(z.prev, z.cur)).toBe(false);
    expect(overlaps(z.cur, z.next)).toBe(false);
    expect(overlaps(z.prev, z.next)).toBe(false);
    for (const k of ['prev', 'cur', 'next'] as const) expect(await insideScreenX(z[k])).toBe(true);
    expect(notTruncated(z.prev, n.prev)).toBe(true);
    expect(notTruncated(z.next, n.next)).toBe(true);
    // Глазами по q33-chapter-nav.png: «פרק ד׳» не «רק ד׳», «פרק ב׳» не прикрыт кругом.
  });
});
